L12_1.m_Crash = 20
L12_1.m_Talk_KOREA = "\234\183\184\235\159\188 \235\139\185\236\151\176\237\158\136 \235\172\180\236\130\172\237\149\152\236\163\160! \235\172\180\237\132\177\235\140\128\234\179\160 \235\179\145\236\155\144\236\157\132 \236\167\128\237\130\164\235\157\188\235\141\148\235\139\136 \236\130\180\236\149\132\236\158\136\236\167\128\235\143\132 \235\170\187\237\149\160 \236\164\132 \236\149\140\236\149\152\236\150\180\236\154\148?!"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "\231\132\161\228\186\139\227\129\171\230\177\186\227\129\190\227\129\163\227\129\166\227\130\139\227\129\152\227\130\131\227\129\170\227\129\132\227\129\167\227\129\153\227\129\139\239\188\129\n\231\151\133\233\153\162\227\130\146\228\187\187\227\129\155\227\129\166\227\129\138\227\129\132\227\129\166\227\128\129\230\173\187\227\130\147\227\129\167\227\130\139\227\129\168\227\129\167\227\130\130\230\128\157\227\129\163\227\129\159\227\130\147\227\129\167\227\129\153\227\129\139\239\188\129\239\188\159"
L12_1.m_Talk_ENG = "Of course I\226\128\153m okay! You\226\128\153re the one who asked me to protect the hospital. Did you think I was going to die or something?"
L12_1.m_Talk_TWN = "\231\149\182\231\132\182\230\178\146\228\186\139\229\155\137\239\188\129\228\189\160\229\143\171\230\136\145\229\174\136\232\173\183\233\134\171\233\153\162\239\188\140\229\141\187\228\187\165\231\130\186\230\136\145\230\178\146\230\156\172\228\186\139\230\180\187\229\145\189\229\151\142\239\188\159"
L12_1.m_Talk_THA = "\224\185\129\224\184\171\224\184\135\224\184\165\224\185\136\224\184\176 \224\184\137\224\184\177\224\184\153\224\184\149\224\185\137\224\184\173\224\184\135\224\185\132\224\184\161\224\185\136\224\185\128\224\184\155\224\185\135\224\184\153\224\185\132\224\184\163\224\184\170\224\184\180! \224\184\129\224\185\135\224\185\128\224\184\152\224\184\173\224\185\128\224\184\155\224\185\135\224\184\153\224\184\132\224\184\153\224\184\130\224\184\173\224\185\131\224\184\171\224\185\137\224\184\137\224\184\177\224\184\153\224\184\155\224\184\129\224\184\155\224\185\137\224\184\173\224\184\135\224\185\130\224\184\163\224\184\135\224\184\158\224\184\162\224\184\178\224\184\154\224\184\178\224\184\165\224\184\153\224\184\181\224\185\136 \224\184\132\224\184\180\224\184\148\224\184\167\224\185\136\224\184\178\224\184\137\224\184\177\224\184\153\224\184\136\224\184\176\224\184\149\224\184\178\224\184\162\224\184\173\224\184\176\224\185\132\224\184\163\224\185\129\224\184\154\224\184\154\224\184\153\224\184\177\224\185\137\224\184\153\224\185\128\224\184\171\224\184\163\224\184\173?"
L12_1.m_Talk_VTN = "T\225\186\165t nhi\195\170n l\195\160 t\195\180i kh\195\180ng sao! C\225\186\173u l\195\160 ng\198\176\225\187\157i \196\145\195\163 y\195\170u c\225\186\167u t\195\180i b\225\186\163o v\225\187\135 b\225\187\135nh vi\225\187\135n. C\225\186\173u ngh\196\169 t\195\180i s\225\186\189 ch\225\186\191t hay th\225\186\191 n\195\160o?"
L12_1.m_Talk_SCN = "\229\189\147\231\132\182\230\178\161\228\186\139\229\149\166\239\188\129\228\189\160\228\184\141\230\152\175\232\175\180\232\174\169\230\136\145\228\191\157\230\138\164\229\140\187\233\153\162\229\144\151\239\188\159\233\154\190\233\129\147\228\187\165\228\184\186\230\136\145\228\188\154\229\176\177\232\191\153\228\185\136\232\183\145\230\142\137\239\188\159"
L12_1.m_Talk_DEU = "Nat\195\188rlich geht es mir gut! Du hast mich gebeten, das Krankenhaus zu besch\195\188tzen. Hast du etwa gedacht, ich w\195\188rde sterben oder so?"
L12_1.m_Talk_FRA = "Bien s\195\187r que je vais bien ! Tu m'as demand\195\169 de surveiller l'h\195\180pital, je te rappelle ! Tu pensais que j'allais mourir ou quoi ?"
